		function currentSlot() {
			var h = new Date().getHours();
			for (var i = 0; i < TIME_SLOTS.length; i++) {
				var s = TIME_SLOTS[i];
				if (s.from < s.to) {
					if (h >= s.from && h < s.to) return s;
				} else {
					if (h >= s.from || h < s.to) return s; // 深夜跨天
				}
			}
			return TIME_SLOTS[0];
		}

