		function safeGet(key, fallback) {
			try {
				var raw = window.localStorage.getItem(key);
				return raw === null ? fallback : raw;
			} catch (e) {
				return fallback;
			}
		}
		function safeSet(key, value) {
			try {
				window.localStorage.setItem(key, value);
			} catch (e) { /* 隐私模式下静默失败 */ }
		}
		function readInterval(config) {
			var ms = DEFAULT_INTERVAL_MS;
			try {
				var fromLs = parseInt(window.localStorage.getItem(LS_INTERVAL), 10);
				if (Number.isFinite(fromLs) && fromLs >= 5000) ms = fromLs;
			} catch (e) { /* ignore */ }
			if (config && Number.isFinite(config.intervalMs) && config.intervalMs >= 5000) {
				ms = config.intervalMs;
			}
			return Math.min(ms, 60000);
		}

